<?php
require_once dirname(__DIR__) . '/core/Controller.php'; require_once dirname(__DIR__) . '/models/Sale.php'; require_once dirname(__DIR__) . '/models/Client.php';
class SalesController extends Controller { private Sale $model; private Client $clients; public function __construct(){ $this->model=new Sale();$this->clients=new Client(); } public function index():void{$this->requireModuleAccess('sales', ['Administrator','Sales Officer']);$this->view('sales/index',['title'=>'Sales','sales'=>$this->model->all(),'clients'=>$this->clients->all()]);} public function create():void{$this->requireLogin();if($_SERVER['REQUEST_METHOD']==='POST'&&$this->validateCsrf())$this->model->create($_POST+['sales_person_id'=>$_SESSION['user']['id']??null]);$this->redirect('/index.php?controller=sales');} public function status():void{$this->requireLogin();if($_SERVER['REQUEST_METHOD']==='POST'&&$this->validateCsrf())$this->model->updateStatus($this->sanitizeInt($_POST['id']??0),$this->sanitize($_POST['status']??'draft'));$this->redirect('/index.php?controller=sales');} }
